begin;
create or replace function pg_temp.expect_mobile_error(statement text,marker text)returns void language plpgsql as $$begin execute statement;raise exception'expected %',marker;exception when others then if sqlerrm not like'%'||marker||'%'then raise;end if;end$$;
do $$
declare
 owner uuid:='5d000000-0000-4000-8000-000000000001';other_user uuid:='5d000000-0000-4000-8000-000000000002';admin_user uuid:='5d000000-0000-4000-8000-000000000003';
 admin_allow uuid:='5d000000-0000-4000-8000-000000000004';creator uuid:='5d000000-0000-4000-8000-000000000005';event_id uuid:='5d000000-0000-4000-8000-000000000006';context_id uuid:='5d000000-0000-4000-8000-000000000007';
 source_id uuid;activity_id uuid;session_id uuid;session_version integer;result jsonb;qr jsonb;resolved jsonb;stamp_qr jsonb;awarded_stamp_id uuid;
 benefit_id uuid:='5d000000-0000-4000-8000-000000000020';policy_id uuid:='5d000000-0000-4000-8000-000000000021';prize_id uuid:='5d000000-0000-4000-8000-000000000022';draw_id uuid:='5d000000-0000-4000-8000-000000000023';award_id uuid:='5d000000-0000-4000-8000-000000000024';
 quiz_id uuid:='5d000000-0000-4000-8000-000000000030';attempt_id uuid:='5d000000-0000-4000-8000-000000000031';pass_id uuid:='5d000000-0000-4000-8000-000000000032';fan_passport_id uuid:='5d000000-0000-4000-8000-000000000033';job_id uuid:='5d000000-0000-4000-8000-000000000034';claim_id uuid:='5d000000-0000-4000-8000-000000000035';q_space_id uuid:='5d000000-0000-4000-8000-000000000036';other_space_id uuid;
begin
 insert into public.app_users(id,privy_user_id,verified_email)values(owner,'did:privy:hardening-owner','hardening-owner@example.test'),(other_user,'did:privy:hardening-other','hardening-other@example.test'),(admin_user,'did:privy:hardening-admin','hardening-admin@example.test');
 insert into public.admin_allowlist(id,email,role,active)values(admin_allow,'hardening-admin@example.test','operator',true);
 insert into public.celebrities(id,slug,status,image_url,roles,primary_role)values(creator,'hardening-source','draft','/hardening.webp','{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt)values(creator,'ko','강화 테스트','설명','이미지'),(creator,'en','Hardening test','Summary','Image');update public.celebrities set status='published',published_at=pg_catalog.clock_timestamp()where id=creator;
 insert into public.mobile_participation_events(id,slug,celebrity_id,event_kind,policy_version,state,starts_at,ends_at,title_ko,title_en)values(event_id,'hardening-event',creator,'byus_day','hardening-v1','published',pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'1 hour','행사','Event');
 insert into public.mobile_participation_contexts(id,context_type,source_event_id,celebrity_id,slug,policy_version,state,opens_at,closes_at,require_checkin,album_kind)values(context_id,'album',event_id,creator,'hardening-album','hardening-v1','published',pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'1 hour',false,'byus_day');
 insert into public.mobile_participation_checkins(event_id,app_user_id,status,source,policy_version)values(event_id,owner,'valid','linked_web','hardening-v1');
 result:=public.upsert_admin_mobile_participation_activity_source(admin_user,admin_allow,null,null,'video','https://media.byus.test/activity.webm',20000,'active','공식 재생 소스를 등록합니다.',extensions.gen_random_uuid());source_id:=(result->>'id')::uuid;
 result:=public.upsert_admin_mobile_participation_activity_v2(admin_user,admin_allow,null,null,context_id,source_id,'activity-v2','video','published',pg_catalog.clock_timestamp()-interval'1 minute',pg_catalog.clock_timestamp()+interval'1 hour',3,10,null,'재생 검증 활동을 게시합니다.',extensions.gen_random_uuid());activity_id:=(result->>'id')::uuid;
 perform pg_temp.expect_mobile_error(format($q$insert into public.mobile_participation_activity_policies(context_id,policy_version,activity_kind,state,opens_at,closes_at,completion_seconds,max_heartbeat_gap_seconds)values(%L,'source-less','video','published',clock_timestamp(),clock_timestamp()+interval'1 hour',3,10)$q$,context_id),'mobile_participation_published_activity_source');
 result:=public.start_owned_mobile_participation_activity(owner,activity_id,'5d000000-0000-4000-8000-000000000010');session_id:=(result->>'id')::uuid;
 if result#>>'{source,playbackUrl}'<>'https://media.byus.test/activity.webm'then raise exception'official source missing from start: %',result;end if;
 update public.mobile_participation_activity_sessions set last_heartbeat_at=pg_catalog.clock_timestamp()-interval'5 seconds',last_client_monotonic_ms=1000,last_position_ms=0 where id=session_id;
 result:=public.heartbeat_owned_mobile_participation_activity(owner,session_id,1,true,false,5000,6000);if result->>'creditedSeconds'<>'0'or result->>'watchedSeconds'<>'0'then raise exception'paused playback accrued: %',result;end if;
 update public.mobile_participation_activity_sessions set last_heartbeat_at=pg_catalog.clock_timestamp()-interval'5 seconds'where id=session_id;
 result:=public.heartbeat_owned_mobile_participation_activity(owner,session_id,2,true,true,9000,10000);if result->>'creditedSeconds'<>'4'or result->>'watchedSeconds'<>'4'then raise exception'valid playback did not accrue: %',result;end if;
 result:=public.heartbeat_owned_mobile_participation_activity(owner,session_id,3,true,true,9000,10000);if result->>'creditedSeconds'<>'0'or result->>'watchedSeconds'<>'4'then raise exception'duplicate heartbeat accrued: %',result;end if;
 result:=public.claim_mobile_participation_activity_completion(10);session_version:=(result#>>'{items,0,version}')::integer;if session_version is null then raise exception'completion was not claimed';end if;
 perform public.upsert_admin_mobile_participation_activity_source(admin_user,admin_allow,source_id,1,'video','https://media.byus.test/activity.webm',20000,'revoked','보상 전에 재생 소스를 중단합니다.',extensions.gen_random_uuid());
 result:=public.finish_mobile_participation_activity_completion(session_id,session_version,true,null);if result->>'state'<>'rejected'then raise exception'revoked source completed: %',result;end if;

 insert into public.benefits(id,slug,celebrity_id,publication_status,delivery_type,claim_opens_at,claim_closes_at)values(benefit_id,'hardening-pickup',creator,'draft','text',pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'1 day');
 insert into public.benefit_localizations(benefit_id,locale,title,summary,eligibility_label,delivery_label)values(benefit_id,'ko','현장 상품','설명','당첨','현장 수령'),(benefit_id,'en','Pickup prize','Summary','Winner','Pickup');update public.benefits set publication_status='published',published_at=pg_catalog.clock_timestamp()where id=benefit_id;
 result:=public.upsert_admin_mobile_participation_space(admin_user,admin_allow,null,null,creator,'hardening-space','space-v1','published',pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'1 hour',benefit_id,'강화 공간','Hardening space','현장 공간','On-site space','/hardening-space.webp','서울','Seoul','공개 공간과 혜택을 게시합니다.',extensions.gen_random_uuid());q_space_id:=(result->>'id')::uuid;
 result:=public.upsert_admin_mobile_participation_space(admin_user,admin_allow,null,null,creator,'hardening-space-two','space-v1','published',pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'2 hours',null,'강화 공간 2','Hardening space 2','두 번째 현장 공간','Second on-site space',null,'부산','Busan','두 번째 공개 공간을 게시합니다.',extensions.gen_random_uuid());other_space_id:=(result->>'id')::uuid;
 qr:=public.issue_admin_mobile_participation_qr(admin_user,admin_allow,'space','fan_place',q_space_id,null,benefit_id,'/participation/spaces/'||q_space_id::text,'space-v1',pg_catalog.clock_timestamp()+interval'1 hour',false,false,'공간 방문 QR을 발급합니다.',extensions.gen_random_uuid());
 result:=public.resolve_owned_mobile_participation_qr(owner,qr->>'rawCode','5d000000-0000-4000-8000-000000000037');if result#>>'{effect,spaceVisitRecorded}'<>'true'or result#>>'{effect,benefit,state}'<>'available'or result#>>'{effect,benefit,grantedByScan}'<>'false'then raise exception'space visit effect invalid: %',result;end if;
 perform public.resolve_owned_mobile_participation_qr(owner,qr->>'rawCode','5d000000-0000-4000-8000-000000000038');if(select count(*)from public.mobile_participation_space_visits v where v.app_user_id=owner and v.space_id=q_space_id)<>1 then raise exception'space visit was recorded more than once';end if;
 result:=public.read_owned_mobile_participation_space(owner,q_space_id,'ko');if result#>>'{space,title}'<>'강화 공간'or result#>>'{visit,completed}'<>'true'or result#>>'{benefit,id}'<>benefit_id::text or result#>>'{benefit,claimState}'<>'not_claimed'or result#>>'{benefit,grantedByVisit}'<>'false'or result#>>'{benefit,perUserLimit}'<>'1'or result#>>'{benefit,claimCount}'<>'0'or result#>>'{benefit,usageCount}'<>'0'or jsonb_array_length(result->'locations')<>2 or not exists(select 1 from jsonb_array_elements(result->'locations')x where(x->>'id')::uuid=other_space_id and x->>'title'='강화 공간 2'and x->>'path'='/spaces/'||other_space_id::text)then raise exception'space read model invalid: %',result;end if;

 insert into public.celebrity_quizzes(id,celebrity_id,version,status)values(quiz_id,creator,1,'draft');
 insert into public.quiz_attempts(id,app_user_id,celebrity_id,quiz_id,quiz_version,idempotency_key,status,score,submitted_at)values(attempt_id,owner,creator,quiz_id,1,extensions.gen_random_uuid(),'passed',3,pg_catalog.now());
 insert into public.quiz_passes(id,app_user_id,celebrity_id,winning_attempt_id)values(pass_id,owner,creator,attempt_id);
 insert into public.blockchain_jobs(id,entity_type,entity_id,operation_key,payload)values(job_id,'passport',fan_passport_id,'participation-benefit-passport','{}');
 alter table public.fan_passports disable trigger fan_passports_validate_blockchain_job_link;
 insert into public.fan_passports(id,app_user_id,celebrity_id,quiz_pass_id,blockchain_job_id)values(fan_passport_id,owner,creator,pass_id,job_id);
 alter table public.fan_passports enable trigger fan_passports_validate_blockchain_job_link;
 insert into public.user_wallets(app_user_id,chain_id,address)values(owner,91342,'0x1111111111111111111111111111111111111111');
 stamp_qr:=public.issue_admin_mobile_participation_qr(admin_user,admin_allow,'stamp','event',event_id,null,null,'/my/activity','hardening-v1',pg_catalog.clock_timestamp()+interval'1 hour',false,false,'검증된 팬에게 출석 스탬프를 발급합니다.',extensions.gen_random_uuid());
 result:=public.resolve_owned_mobile_participation_qr(owner,stamp_qr->>'rawCode','5d000000-0000-4000-8000-000000000040');awarded_stamp_id:=(result#>>'{effect,stamp,id}')::uuid;
 if result->>'status'<>'resolved'or result#>>'{effect,stampRecorded}'<>'true'or result#>>'{effect,stamp,passportId}'<>fan_passport_id::text or result#>>'{effect,stamp,scorePoints}'<>'3'or result->>'destinationPath'<>('/stamps/'||awarded_stamp_id::text)or not exists(select 1 from public.stamps s where s.id=awarded_stamp_id and s.passport_id=fan_passport_id and s.stamp_type='attendance')or not exists(select 1 from public.fan_activities a where a.id=(result#>>'{effect,stamp,activityId}')::uuid and a.source_type='mobile_participation_qr_stamp')or(select coalesce(sum(l.points),0)from public.fan_score_ledger l where l.app_user_id=owner and l.celebrity_id=creator)<>3 then raise exception'stamp did not integrate owned credential records: %',result;end if;
 result:=public.read_owned_mobile_passports(owner,'ko');if not exists(select 1 from jsonb_array_elements(result->'passports') p where p->>'kind'='favorite' and p->>'stampCount'='1' and p->>'fanXp'='3')then raise exception'passport projection omitted QR stamp: %',result;end if;
 result:=public.read_owned_mobile_profile(owner,'ko');if(result#>>'{counts,stamps}')::integer<1 or(result#>>'{passports,stampCount}')::integer<1 or result#>>'{recentActivity,kind}'<>'fan_activity'then raise exception'profile projection omitted QR stamp: %',result;end if;
 result:=public.resolve_owned_mobile_participation_qr(owner,stamp_qr->>'rawCode','5d000000-0000-4000-8000-000000000041');if result#>>'{effect,stamp,id}'<>awarded_stamp_id::text or(select count(*)from public.stamps where app_user_id=owner and celebrity_id=creator)<>1 or(select count(*)from public.fan_score_ledger where app_user_id=owner and celebrity_id=creator)<>1 then raise exception'reusable stamp QR duplicated credentials: %',result;end if;
 insert into public.benefit_claims(id,benefit_id,app_user_id,celebrity_id,passport_id,idempotency_key,delivery_type,claimed_at)values(claim_id,benefit_id,owner,creator,fan_passport_id,extensions.gen_random_uuid(),'text',pg_catalog.now());
 qr:=public.issue_admin_mobile_participation_qr(admin_user,admin_allow,'benefit_use','benefit_claim',claim_id,owner,benefit_id,'/benefits/'||benefit_id::text,'benefit-use-v1',pg_catalog.clock_timestamp()+interval'1 hour',true,true,'현장 혜택 사용 QR을 발급합니다.',extensions.gen_random_uuid());
 resolved:=public.resolve_owned_mobile_participation_qr(owner,qr->>'rawCode','5d000000-0000-4000-8000-000000000039');if resolved#>>'{effect,benefit,state}'<>'claimed'or resolved#>>'{effect,benefit,grantedByScan}'<>'false'then raise exception'benefit scan granted or consumed before staff confirmation: %',resolved;end if;
 result:=public.confirm_admin_mobile_participation_qr(admin_user,admin_allow,(resolved->>'requestId')::uuid,'현장 담당자가 혜택 사용을 확인했습니다.',extensions.gen_random_uuid());if result#>>'{effect,benefit,state}'<>'used'or(select count(*)from public.benefit_claim_usage_events where benefit_claim_id=claim_id)<>1 then raise exception'benefit confirmation did not consume existing claim: %',result;end if;
 result:=public.read_owned_mobile_participation_space(owner,q_space_id,'ko');if result#>>'{benefit,claimCount}'<>'1'or result#>>'{benefit,usageCount}'<>'1'or result#>>'{benefit,claimState}'<>'used'then raise exception'benefit usage projection invalid: %',result;end if;
 insert into public.mobile_benefit_policies(id,benefit_id,mode,policy_version,ticket_cost,enabled,opens_at,closes_at)values(policy_id,benefit_id,'instant_draw','pickup-v1',1,false,pg_catalog.clock_timestamp()-interval'1 hour',pg_catalog.clock_timestamp()+interval'1 hour');
 insert into public.mobile_benefit_instant_prizes(id,policy_id,outcome,weight,inventory_limit,inventory_awarded,fulfillment_method)values(prize_id,policy_id,'won',1,1,1,'on_site_pickup');
 insert into public.mobile_benefit_draw_requests(id,app_user_id,benefit_id,celebrity_id,policy_id,policy_version,prize_id,outcome,entropy_hash,free_tickets_used,paid_tickets_used,usage_date)values(draw_id,owner,benefit_id,creator,policy_id,'pickup-v1',prize_id,'won',repeat('a',64),1,0,current_date);
 insert into public.mobile_benefit_awards(id,draw_request_id,app_user_id,benefit_id,prize_id,fulfillment_method,fulfillment_status)values(award_id,draw_id,owner,benefit_id,prize_id,'on_site_pickup','pickup_available');
 qr:=public.issue_owned_mobile_benefit_pickup_qr(owner,award_id,'5d000000-0000-4000-8000-000000000025');if qr->>'purpose'<>'prize_pickup'or qr->>'staffConfirmationRequired'<>'true'then raise exception'pickup QR contract invalid: %',qr;end if;
 result:=public.issue_owned_mobile_benefit_pickup_qr(owner,award_id,'5d000000-0000-4000-8000-000000000025');if result->>'rawCode'<>qr->>'rawCode'or result->>'replayed'<>'true'then raise exception'pickup QR replay changed: %',result;end if;
 if public.read_owned_mobile_benefit_pickup_qr(owner,award_id)->>'rawCode'<>qr->>'rawCode'then raise exception'pickup QR read missing';end if;
 result:=public.resolve_owned_mobile_participation_qr(owner,qr->>'rawCode','5d000000-0000-4000-8000-000000000026');if result->>'status'<>'resolved'or result->>'staffConfirmationRequired'<>'true'then raise exception'pickup QR owner resolution invalid: %',result;end if;
 result:=public.resolve_owned_mobile_participation_qr(other_user,qr->>'rawCode','5d000000-0000-4000-8000-000000000027');if result->>'status'<>'unknown'or result->'effect'<>'null'::jsonb or result->'consumedAt'<>'null'::jsonb then raise exception'active owner-bound QR leaked private state: %',result;end if;
 resolved:=public.resolve_admin_mobile_participation_qr(admin_user,admin_allow,qr->>'rawCode','5d000000-0000-4000-8000-000000000028');if resolved->>'status'<>'resolved'or resolved->>'staffConfirmationRequired'<>'true'then raise exception'staff scan did not resolve owner-bound QR: %',resolved;end if;
 result:=public.confirm_admin_mobile_participation_qr(admin_user,admin_allow,(resolved->>'requestId')::uuid,'현장 담당자가 상품 수령을 확인했습니다.',extensions.gen_random_uuid());
 if result->>'status'<>'consumed'or result->>'staffConfirmationRequired'<>'true'or(select fulfillment_status from public.mobile_benefit_awards where id=award_id)<>'pickup_completed'then raise exception'pickup confirmation did not complete award: %',result;end if;
 result:=public.resolve_owned_mobile_participation_qr(other_user,qr->>'rawCode','5d000000-0000-4000-8000-000000000029');if result->>'status'<>'unknown'or result->'effect'<>'null'::jsonb or result->'consumedAt'<>'null'::jsonb then raise exception'consumed owner-bound QR leaked private state: %',result;end if;
 if public.read_owned_mobile_benefit_pickup_qr(owner,award_id)is not null then raise exception'consumed pickup QR remained readable';end if;
end$$;
rollback;
